395	// ── Certificate states ───────────────────────────────────────────────────────
396	
397	// The monitors' vocabulary does not say what a certificate is. `up` named
398	// "reachable" which means "valid", and `error` received both the expired one
399	// and the one expiring next week.
400	func TestTheCertificateTreeSpeaksOfCertificates(t *testing.T) {
401		m := healthModel(t, []status.ComponentStatus{
402			{Name: "web", Type: status.TypeHTTPS, Status: status.StatusOK},
403			certWithDays("google.com", 58),
404		})
405		_, certs := healthColumns(m)
406	
407		for _, label := range []string{"valid", "to renew", "expired", "error", "expiry"} {
408			if nodeUnder(certs, "Certs", label) == "" {
409				t.Errorf("the Certs tree has no %q node", label)
410			}
411		}
412		for _, label := range []string{"up", "down"} {
413			if got := nodeUnder(certs, "Certs", label); got != "" {
414				t.Errorf("the Certs tree kept the monitor node %q: %q", label, got)
415			}
416		}
417	
418		// Monitors keep their own, and don't borrow the other way around.
419		monitors, _ := healthColumns(m)
420		for _, label := range []string{"up", "down", "error"} {
421			if nodeUnder(monitors, "Monitors", label) == "" {
422				t.Errorf("the Monitors tree lost its %q node", label)
423			}
424		}
425		for _, label := range []string{"valid", "to renew", "expired"} {
426			if got := nodeUnder(monitors, "Monitors", label); got != "" {
427				t.Errorf("the Monitors tree grew the certificate node %q: %q", label, got)
428			}
429		}
430	}
431	
432	// The bug, counted: three certificates that `up` / `down` / `error` put
433	// into two buckets are now split across three.
434	func TestAnExpiredCertificateIsNotCountedAsAReadFailure(t *testing.T) {
435		m := healthModel(t, []status.ComponentStatus{
436			certWithDays("far", 300),
437			certWithDays("soon", 9),
438			certWithDays("gone", -2),
439			{Name: "unreachable", Type: status.TypeSSL, Status: status.StatusDown},
440		})
441		_, certs := healthColumns(m)
442	
443		for _, c := range []struct{ label, want string }{
444			{"valid", "1"},
445			{"to renew", "1"},
446			{"expired", "1"},
447			{"error", "1"},
448		} {
449			got := stripANSI(nodeUnder(certs, "Certs", c.label))
450			if !strings.Contains(got, c.want) {
451				t.Errorf("the %q node reads %q, want a count of %s", c.label, got, c.want)
452			}
453		}
454	}
455	
456	// Each state carries its own glyph, including at zero: without that,
457	// `expired` and `error` carried the same alert and became one line read as
458	// two.
